local function IsInRange(p1, p2, range)
	p2 = p2 or myHero
	p1 = p1.pos or p1
	p2 = p2.pos or p2
	local dx = p1.x - p2.x
	local dy = (p1.z or p1.y) - (p2.z or p2.y)
	return dx * dx + dy * dy <= range * range
end

local function GetDistance(p1, p2)
	p2 = p2 or myHero
	p1 = p1.pos or p1
	p2 = p2.pos or p2
	local dx = p1.x - p2.x
	local dy = (p1.z or p1.y) - (p2.z or p2.y)
	return math.sqrt(dx * dx + dy * dy)
end

local function ClearArray(t)
	for i = #t, 1, -1 do
		t[i] = nil
	end
end

local function ClearMap(t)
	for k in pairs(t) do
		t[k] = nil
	end
end

local function Polar(v1)
	local x = v1.x
	local z = v1.z or v1.y
	if x == 0 then
		if z > 0 then
			return 90
		end
		return z < 0 and 270 or 0
	end
	local theta = math_atan(z / x) * (180.0 / math_pi)
	if x < 0 then
		theta = theta + 180
	end
	if theta < 0 then
		theta = theta + 360
	end
	return theta
end

local function AngleBetween(vec1, vec2)
	local theta = Polar(vec1) - Polar(vec2)
	if theta < 0 then
		theta = theta + 360
	end
	if theta > 180 then
		theta = 360 - theta
	end
	return theta
end

local function IsFacing(source, target, angle)
	angle = angle or 90
	target = target.pos or Vector(target)
	return AngleBetween(source.dir, target - source.pos) < angle
end

local function Base64Decode(data)
	local b = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	data = string.gsub(data, "[^" .. b .. "=]", "")
	return (
		data:gsub(".", function(x)
			if x == "=" then
				return ""
			end
			local r, f = "", (b:find(x) - 1)
			for i = 6, 1, -1 do
				r = r .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
			end
			return r
		end):gsub("%d%d%d?%d?%d?%d?%d?%d?", function(x)
			if #x ~= 8 then
				return ""
			end
			local c = 0
			for i = 1, 8 do
				c = c + (x:sub(i, i) == "1" and 2 ^ (8 - i) or 0)
			end
			return string.char(c)
		end)
	)
end

local function WriteToFile(path, str)
	path = SPRITE_PATH .. path
	if FileExist(path) then
		return
	end
	local output = io.open(path, "wb")
	output:write(Base64Decode(str))
	output:close()
end

local function GetControlPos(a, b, c)
	local pos
	if a and b and c then
		pos = { x = a, y = b, z = c }
	elseif a and b then
		pos = { x = a, y = b }
	elseif a then
		pos = a.pos or a
	end
	return pos
end

local function CastKey(key)
	if key == MOUSEEVENTF_RIGHTDOWN then
		Control.mouse_event(MOUSEEVENTF_RIGHTDOWN)
		Control.mouse_event(MOUSEEVENTF_RIGHTUP)
	else
		Control.KeyDown(key)
		Control.KeyUp(key)
	end
end

