			or wParam == menuKeys[ORBWALKER_MODE_FLEE][1]:Key()
			or wParam == menuKeys[ORBWALKER_MODE_HARASS][1]:Key()
			or wParam == menuKeys[ORBWALKER_MODE_LANECLEAR][1]:Key()
			or wParam == menuKeys[ORBWALKER_MODE_JUNGLECLEAR][1]:Key()
