    MasterYi={{slot=1,name='Meditate'}},Jade_MasterYi={{slot=1,name='Jade_MasterYiMeditate'}},
    Jade_Wukong={{slot=0,name='Jade_WukongQ'}},
    Nasus={{slot=0,name='NasusQ',buff='NasusQ'}},
    Jade_Nasus={{slot=0,name='Jade_NasusQ',buff='Jade_NasusQ'},{slot=0,name='Jade_NasusSiphoningStrike',buff='Jade_NasusQ'}}}

end)(),{[0]=HK_Q,[1]=HK_W,[2]=HK_E,[3]=HK_R})
