   local q=hero:GetSpellData(0)
   if q and live.name==q.name then
    if state.qKey~=live.castEndTime then state.qKey=live.castEndTime;forget('q_cast')end
   elseif(live.isAutoAttack or Data:IsAttack(live.name))and type(live.target)=='number'and live.target>0
    and live.castEndTime>state.attackKey then
