-- One provider lifetime. Late host callbacks must not resume a retired SDK.
return function(g,sdk,input,hero)
    local game=g.Game
    local timer,latency=game.Timer,game.Latency
    local stopped=false
    function sdk:Shutdown(reason)
        if stopped then return false end
        stopped=true;self.Stopped=true;self.stopReason=reason or 'unload'
