        if core then pcall(core.Shutdown,core,self.stopReason)end
        if self.Actions then
            for id in pairs(self.Actions.scopes)do pcall(self.Actions.CloseScope,self.Actions,id,self.stopReason)end
        end
        if self.Preparation then
            for _,scope in pairs(self.Preparation.scopes)do pcall(scope.Close,scope)end
        end
        if self.Overlay then
            for _,scope in pairs(self.Overlay.scopes)do pcall(scope.Close,scope)end
        end
        input:Shutdown()
        return true
    end
    g.Callback.Add('UnLoad',function()sdk:Shutdown('unload')end)
    local function alive()
        if stopped then return false end
        if g.SDK~=sdk or g.myHero~=hero or g.Game~=game
            or game.Timer~=timer or game.Latency~=latency then
            sdk:Shutdown('host_unavailable');return false
        end
        return true
    end
    local function finish(ok,...)
        sdk.DispatchDepth=sdk.DispatchDepth-1
        if not ok then error((...),0)end
        return ...
    end
    local function dispatch(fn,...)
        sdk.DispatchDepth=(sdk.DispatchDepth or 0)+1
        return finish(pcall(fn,...))
    end
    local frames,depth={},0
    local function runCallbacks(list,label,frame,count,...)
        for i=1,count do
            if sdk.Stopped then return false end
            local fn=frame[i];local registered=fn and list[i]==fn
            if fn and not registered then
                for j=1,#list do if list[j]==fn then registered=true;break end end
            end
            if registered then
                if label and sdk.Performance.enabled then sdk.Performance:Call(label,fn,...)
                else fn(...)end
            end
        end
        return not sdk.Stopped
    end
    local function finishCallbacks(frame,count,ok,...)
        for i=1,count do frame[i]=nil end
        depth=depth-1
        if not ok then error((...),0)end
        return ...
    end
    local function callbacks(list,label,...)
        depth=depth+1;local frame=frames[depth]or{};frames[depth]=frame
        local count=#list;for i=1,count do frame[i]=list[i]end
        return finishCallbacks(frame,count,pcall(runCallbacks,list,label,frame,count,...))
    end
