SDK.UIInput=(function()
return function(input)
    local ui={version=1,handlers={}}
    function ui:Register(owner,handler,active)
        assert(owner~=nil and type(handler)=='function' and type(active)=='function','UI input requires an owner and activity check')
        for _,row in ipairs(self.handlers) do
            if row.owner==owner then return nil,'owner_registered' end
        end
        if #self.handlers>=16 then return nil,'handler_limit' end
        local row={owner=owner,handler=handler,active=active}
        self.handlers[#self.handlers+1]=row
        local closed=false
        return {Close=function()
            if closed then return end;closed=true
            for i=#ui.handlers,1,-1 do if ui.handlers[i]==row then table.remove(ui.handlers,i);break end end
        end}
    end
    function ui:Handle(msg,key)
        if input:IsSyntheticEvent() then return false end
        for i=#self.handlers,1,-1 do
            local row=self.handlers[i]
            local ok,active=pcall(row.active)
            if not ok or not active then table.remove(self.handlers,i)
            else
                local good,consumed=pcall(row.handler,msg,key)
                if not good then table.remove(self.handlers,i)
                elseif consumed==true then return true end
            end
        end
        return false
    end
    return ui
end

end)()(Cursor)
