        return true
    end
    function C:SubmitKeyed(key,intent,equivalent)
        if self.resolving or type(key)~='string'or #key>160 or type(intent)~='table'
            or not rank[intent.priority or 'normal']then return nil,'invalid_intent_key'end
        local previous=self.keyed[key];local record=previous and self:Poll(previous)
        if record and not record.sentAt and(record.state=='waiting'or record.state=='requested')then
