    function C:IsSending()return transport.sending==true end
    function C:Condition(owner,name,condition,exceptions)
        if self.resolving then return false,'resolver_side_effect'end

        assert(type(condition)=='function');local token={owner=owner,name=name,condition=condition,exceptions=exceptions}
        self.gates[token]=true;return token
    end
    function C:ReleaseCondition(token)
        if self.resolving then return false,'resolver_side_effect'end
if self.gates[token]then self.gates[token]=nil;return true end;return false end
    function C:ContextValid(q,phase)
        if self.closed or not active() or(g.myHero.dead and not(q.cleanupOnly==true and q.type=='key'))
            or g.Game.IsChatOpen() or not g.Game.IsOnTop() then return false,'context_unavailable' end
        if self.evadePolicy and sdk.Evade and type(sdk.Evade.Evading)=='function' and sdk.Evade:Evading()and not q.evadeCompatible then return false,'evade_intervention'end
        local c=q.context
        if c then
            if c.modes then local yes=false;for _,mode in ipairs(c.modes)do if sdk.Orbwalker.Modes[mode]then yes=true end end;if not yes then return false,'mode_ended' end end
            if c.held and not call(c.held)then return false,'binding_released'end
            if c.condition and not call(c.condition,q)then return false,'context_condition_ended'end
        end
        if phase~='continuation' then
        for gate in pairs(self.gates)do
            if not (q.exceptions and q.exceptions[gate.name] and gate.exceptions and gate.exceptions[q.exceptions[gate.name]]) then
                if not call(gate.condition,q)then return false,'condition:'..gate.name end
            end
        end
        end
        return true
    end
    function C:Poll(id)return transport:Poll(id)end
    -- Read-only inspection of the existing lease. No admission, reconciliation,
    -- cursor acquisition or timer is performed by these queries.
    function C:HasAction(id)return self.jobs[id]~=nil end
    function C:HasWork()return next(self.jobs)~=nil end
    function C:ResourceAction(resource,includeReceipt)
        if type(resource)~='string'or resource==''or #resource>160 then return nil,nil,'invalid_resource'end
        local lease=hub.resources[resource]
        if lease then
            if lease.client~=self then return nil,nil,'foreign_resource_reserved'end
            return lease.id,includeReceipt~=false and self:Poll(lease.id)or nil,'resource_reserved'
        end
        local reservation=hub.reservations[resource]
        if reservation then return nil,nil,reservation.client==self and'plan_resource_reserved'or'foreign_resource_reserved'end
        return nil,nil,nil
    end
    function C:PollDependency(id,grant)
        if not grant then return self:Poll(id)end
        return transport:PollDependency(id,grant)
    end
    function C:AuthorizeDependency(id,borrower,opts)
        if self.closed or self.resolving or not active()then return nil,'inactive_or_resolver'end
        local source=self.jobs[id]
        if not source or source.cancelled or not borrower or hub.clients[borrower.id]~=borrower
            or borrower.closed or not borrower:IsActive() or type(opts)~='table'then return nil,'invalid_dependency_grant'end
