  local ok,count=pcall(game.MissileCount)
  if not ok or not finite(count)or count<0 or count~=math.floor(count)then return nil,'missile_snapshot_invalid',1 end
  if count>math.min(limit or self.maxInventory,self.maxInventory)then return nil,'missile_scan_budget',1 end
